#!/bin/sh
# Remove everything generated by split_data.py/train.py/explore_data.py
# (split csv files, saved model, metrics history, graphs), so it can be
# regenerated from scratch.

FILES="data/data_train.csv data/data_valid.csv saved_model.npz"
DIRS="history outputs"

for f in $FILES; do
    if [ -f "$f" ]; then
        rm "$f"
        echo "removed $f"
    else
        echo "skipped $f (not found)"
    fi
done

for d in $DIRS; do
    if [ -d "$d" ]; then
        rm -r "$d"
        echo "removed $d/"
    else
        echo "skipped $d/ (not found)"
    fi
done
